const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      workflowName: 'Data Scraping + Processing',
      companyName: body.companyName || 'ABM Solutions Demo',
      sourceUrl: body.sourceUrl || '',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const data = $input.first().json;
const suppliedRecords = data.payload?.records;

const demoRecords = [
  {
    name: 'Acme Manufacturing',
    website: 'https://acme.example',
    email: 'sales@acme.example',
    employees: '120'
  },
  {
    name: ' Acme Manufacturing ',
    website: 'https://acme.example/',
    email: 'SALES@ACME.EXAMPLE',
    employees: 120
  },
  {
    name: 'Nova Labs',
    website: 'nova.example',
    email: 'hello@nova.example',
    employees: '45'
  },
  {
    name: 'Summit Logistics',
    website: 'summit.example',
    email: 'invalid-email',
    employees: '250'
  },
  {
    name: '',
    website: 'https://unknown.example',
    email: 'contact@unknown.example',
    employees: '30'
  }
];

const records =
  Array.isArray(suppliedRecords) && suppliedRecords.length > 0
    ? suppliedRecords
    : demoRecords;

return [{
  json: {
    ...data,
    records
  }
}];

const data = $input.first().json;
const records = Array.isArray(data.records) ? data.records : [];

const validRecords = [];
const rejectedRecords = [];

for (const record of records) {
  const name = String(record.name || '').trim();
  const email = String(record.email || '').trim().toLowerCase();

  const employees = Math.max(
    0,
    Number.parseInt(
      String(record.employees || '0').replace(/,/g, ''),
      10
    ) || 0
  );

  let website = String(record.website || '').trim().toLowerCase();

  if (website && !/^https?:\/\//i.test(website)) {
    website = `https://${website}`;
  }

  website = website.replace(/\/+$/, '');

  const validEmail =
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  const validWebsite =
    /^https?:\/\/[a-z0-9.-]+\.[a-z]{2,}(?:[/:?#]|$)/i.test(website);

  if (!name || !validEmail || !validWebsite) {
    rejectedRecords.push({
      originalRecord: record,
      rejectionReason: !name
        ? 'Missing name'
        : !validEmail
          ? 'Invalid email'
          : 'Invalid website'
    });

    continue;
  }

  validRecords.push({
    name,
    website,
    email,
    employees
  });
}

const uniqueRecords = new Map();

for (const record of validRecords) {
  const duplicateKey = `${record.website}|${record.email}`;

  if (!uniqueRecords.has(duplicateKey)) {
    uniqueRecords.set(duplicateKey, record);
  }
}

const cleanedRecords = [...uniqueRecords.values()];

return [{
  json: {
    ...data,
    result: {
      records: cleanedRecords,
      rejectedRecords,
      inputCount: records.length,
      outputCount: cleanedRecords.length,
      duplicatesRemoved: validRecords.length - cleanedRecords.length,
      invalidRecordsRemoved: rejectedRecords.length
    }
  }
}];
